select sync.id as id,
       sync.cust_num as custNum,
       sync.cell as cell,
       reserve_field1
from b_marketing_sync_${apiCode} sync
left join b_third_partner_data_pass_back_log passLog on sync.id = passLog.sync_user_id
    AND passLog.task_id = #{taskId}
    AND passLog.status in (0,1)

    sync.api_code = #{apiCode}
    AND sync.applet_date = #{appletDate}
    AND sync.user_type = #{userType}
    AND sync.status = 1
    AND sync.is_repeat in (1,2)
    AND passLog.id is null
    limit #{pageSize}

