select
  b.*
from b_marketing_sync_${apiCode} as b
LEFT JOIN b_qifu_batch_query_user_real_message bq ON
    b.cell_md5 = bq.mobile_md5 AND b.cust_num = bq.unique_req_no AND bq.create_date = #{createDate}
where b.api_code =#{apiCode}
  AND b.cus_batch =#{cusBatch}
  AND b.status=1
  AND b.is_repeat in (1,2)
  AND bq.mobile_md5 IS NULL

    and b.id > #{minId}

order by b.id asc
limit #{pageSize}

